10	// Regression coverage for snapshot comparison on graphs where several lineage
11	// paths converge at one summary dataset and derivation continues past it.
12	//
13	// The shared fixture keeps two upstream-less roots (rootA, rootB), three
14	// intermediate branches (branchA1 and branchA2 depend only on rootA, branchB1
15	// depends on rootB), one summary where every branch converges, one dataset
16	// derived after the summary, and one unrelated branch (soloRoot/soloChild)
17	// that never changes. The compare reports must keep two questions apart:
18	//
19	//   - changedDatasets / addedRelations / removedRelations answer "which DIRECT
20	//     upstream relationships changed", and never count an indirect path as a
21	//     direct relation;
22	//   - rootSourceChanges answers "which datasets present in BOTH versions reach
23	//     a different set of roots", so a dataset whose direct upstreams are
24	//     unchanged can still appear there when an earlier branch moved, while a
25	//     mere swap onto another path to the SAME root set never appears.
26	//
27	// Both graphs below are legal: every upstream resolves and neither graph has
28	// a cycle.
29	const convergenceOldGraph = `{"datasets":[
30		{"name":"rootA","upstreams":[]},
31		{"name":"rootB","upstreams":[]},
32		{"name":"branchA1","upstreams":["rootA"]},
33		{"name":"branchA2","upstreams":["rootA"]},
34		{"name":"branchB1","upstreams":["rootB"]},
35		{"name":"summary","upstreams":["branchA1","branchA2","branchB1"]},
36		{"name":"derived","upstreams":["summary"]},
37		{"name":"soloRoot","upstreams":[]},
38		{"name":"soloChild","upstreams":["soloRoot"]}
39	]}`
40	
41	// TestCompareConvergenceOneBranchRerouted is the headline case: one branch
42	// that used to depend only on rootA is repointed at rootB; every other
43	// relationship is untouched. The summary and the dataset derived after it can
44	// still reach both roots (rootA survives via branchA2, rootB via branchB1 and
45	// the repointed branch), so they must NOT enter the root-source change list.
46	// The repointed branch itself changes source rootA -> rootB and must be
47	// reported even though the converged summary result is unchanged.
48	func TestCompareConvergenceOneBranchRerouted(t *testing.T) {
49		oldSnap := snapshotOf(t, convergenceOldGraph)
50		newSnap := snapshotOf(t, `{"datasets":[
51			{"name":"rootA","upstreams":[]},
52			{"name":"rootB","upstreams":[]},
53			{"name":"branchA1","upstreams":["rootB"]},
54			{"name":"branchA2","upstreams":["rootA"]},
55			{"name":"branchB1","upstreams":["rootB"]},
56			{"name":"summary","upstreams":["branchA1","branchA2","branchB1"]},
57			{"name":"derived","upstreams":["summary"]},
58			{"name":"soloRoot","upstreams":[]},
59			{"name":"soloChild","upstreams":["soloRoot"]}
60		]}`)
61	
62		report := CompareSnapshots(oldSnap, newSnap)
63	
64		if len(report.NewDatasets) != 0 {
65			t.Errorf("NewDatasets = %v, want []", report.NewDatasets)
66		}
67		if len(report.RemovedDatasets) != 0 {
68			t.Errorf("RemovedDatasets = %v, want []", report.RemovedDatasets)
69		}
70		if got, want := report.ChangedDatasets, []string{"branchA1"}; !reflect.DeepEqual(got, want) {
71			t.Errorf("ChangedDatasets = %v, want %v", got, want)
72		}
73		// Only the two direct edges incident on the repointed branch differ; the
74		// still-reachable rootA -> branchA1 path through branchA2 is indirect and
75		// must not be reported as an added or removed relation.
76		if got, want := report.AddedRelations, []Relation{{Upstream: "rootB", Downstream: "branchA1"}}; !reflect.DeepEqual(got, want) {
77			t.Errorf("AddedRelations = %v, want %v", got, want)
78		}
79		if got, want := report.RemovedRelations, []Relation{{Upstream: "rootA", Downstream: "branchA1"}}; !reflect.DeepEqual(got, want) {
80			t.Errorf("RemovedRelations = %v, want %v", got, want)
81		}
82		wantRootChanges := []RootSourceChange{
83			{Dataset: "branchA1", OldRoots: []string{"rootA"}, NewRoots: []string{"rootB"}},
84		}
85		if got := report.RootSourceChanges; !reflect.DeepEqual(got, wantRootChanges) {
86			t.Errorf("RootSourceChanges = %v, want %v", got, wantRootChanges)
87		}
88	
89		// Explicitly pin the convergence guarantee: the summary still reaches both
90		// roots through its other branches, so neither it nor the dataset derived
91		// after it is a source change despite the repoint upstream of them.
92		for _, name := range []string{"summary", "derived"} {
93			if got := rootSources(name, adjacencyFromValidFile(oldSnap.Graph)); !reflect.DeepEqual(got, []string{"rootA", "rootB"}) {
94				t.Errorf("old rootSources(%s) = %v, want [rootA rootB]", name, got)
95			}
96			if got := rootSources(name, adjacencyFromValidFile(newSnap.Graph)); !reflect.DeepEqual(got, []string{"rootA", "rootB"}) {
97				t.Errorf("new rootSources(%s) = %v, want [rootA rootB]", name, got)
98			}
99		}
100		assertNameAbsentFromReport(t, report, "summary")
101		assertNameAbsentFromReport(t, report, "derived")
102		assertNameAbsentFromReport(t, report, "branchA2")
103		assertNameAbsentFromReport(t, report, "branchB1")
104		assertNameAbsentFromReport(t, report, "soloRoot")
105		assertNameAbsentFromReport(t, report, "soloChild")
106	}
107	
108	// TestCompareConvergenceAllRootAPathsRerouted covers the same converging graph
109	// when the remaining path to rootA (branchA2) is also rewired to rootB. After
110	// the change the summary and the derived dataset can no longer reach rootA,
111	// so both must be listed exactly once with their complete old and new root
112	// sets ([rootA,rootB] -> [rootB]), even though neither dataset's DIRECT
113	// upstreams changed and therefore neither belongs in changedDatasets.
114	func TestCompareConvergenceAllRootAPathsRerouted(t *testing.T) {
115		oldSnap := snapshotOf(t, convergenceOldGraph)
116		newSnap := snapshotOf(t, `{"datasets":[
117			{"name":"rootA","upstreams":[]},
118			{"name":"rootB","upstreams":[]},
119			{"name":"branchA1","upstreams":["rootB"]},
120			{"name":"branchA2","upstreams":["rootB"]},
121			{"name":"branchB1","upstreams":["rootB"]},
122			{"name":"summary","upstreams":["branchA1","branchA2","branchB1"]},
123			{"name":"derived","upstreams":["summary"]},
124			{"name":"soloRoot","upstreams":[]},
125			{"name":"soloChild","upstreams":["soloRoot"]}
126		]}`)
127	
128		report := CompareSnapshots(oldSnap, newSnap)
129	
130		if got, want := report.ChangedDatasets, []string{"branchA1", "branchA2"}; !reflect.DeepEqual(got, want) {
131			t.Errorf("ChangedDatasets = %v, want %v; downstream datasets must not join just because their sources changed", got, want)
132		}
133		if got, want := report.AddedRelations, []Relation{
134			{Upstream: "rootB", Downstream: "branchA1"},
135			{Upstream: "rootB", Downstream: "branchA2"},
136		}; !reflect.DeepEqual(got, want) {
137			t.Errorf("AddedRelations = %v, want %v", got, want)
138		}
139		if got, want := report.RemovedRelations, []Relation{
140			{Upstream: "rootA", Downstream: "branchA1"},
141			{Upstream: "rootA", Downstream: "branchA2"},
142		}; !reflect.DeepEqual(got, want) {
143			t.Errorf("RemovedRelations = %v, want %v", got, want)
144		}
145	
146		// Entries are sorted by dataset name; summary and derived each appear
147		// exactly once, with full sorted root sets on both sides.
148		wantRootChanges := []RootSourceChange{
149			{Dataset: "branchA1", OldRoots: []string{"rootA"}, NewRoots: []string{"rootB"}},
150			{Dataset: "branchA2", OldRoots: []string{"rootA"}, NewRoots: []string{"rootB"}},
151			{Dataset: "derived", OldRoots: []string{"rootA", "rootB"}, NewRoots: []string{"rootB"}},
152			{Dataset: "summary", OldRoots: []string{"rootA", "rootB"}, NewRoots: []string{"rootB"}},
153		}
154		if got := report.RootSourceChanges; !reflect.DeepEqual(got, wantRootChanges) {
155			t.Errorf("RootSourceChanges = %v, want %v", got, wantRootChanges)
156		}
157	
158		// Direct-upstream sets of summary and derived are identical in both
159		// versions: their presence in rootSourceChanges must not also surface them
160		// as direct changes.
161		if containsString(report.ChangedDatasets, "summary") || containsString(report.ChangedDatasets, "derived") {
162			t.Errorf("summary/derived have unchanged direct upstreams but appear in ChangedDatasets %v", report.ChangedDatasets)
163		}
164		// The roots themselves keep reaching only themselves, and the unrelated
165		// branch is untouched. The roots may still appear as endpoints of the
166		// actually added/removed direct edges, so only node lists and the
167		// root-change list are checked here.
168		assertDatasetNotAChange(t, report, "rootA")
169		assertDatasetNotAChange(t, report, "rootB")
170		assertNameAbsentFromReport(t, report, "branchB1")
171		assertNameAbsentFromReport(t, report, "soloRoot")
172		assertNameAbsentFromReport(t, report, "soloChild")
173	}
174	
175	// assertDatasetNotAChange fails if name appears in any node list or as the
176	// dataset of a root-source change. Unlike assertNameAbsentFromReport it does
177	// not inspect relation endpoints, which a root may legitimately touch when an
178	// edge from that root is genuinely added or removed.
179	func assertDatasetNotAChange(t *testing.T, report *CompareReport, name string) {
180		t.Helper()
181		if containsString(report.NewDatasets, name) {
182			t.Errorf("%q must not be a new dataset; report = %+v", name, report)
183		}
184		if containsString(report.RemovedDatasets, name) {
185			t.Errorf("%q must not be a removed dataset; report = %+v", name, report)
186		}
187		if containsString(report.ChangedDatasets, name) {
188			t.Errorf("%q must not be a directly changed dataset; report = %+v", name, report)
189		}
190		for _, change := range report.RootSourceChanges {
191			if change.Dataset == name {
192				t.Errorf("%q must not appear in root source changes; report = %+v", name, report)
193			}
194		}
195	}
196	
197	// TestCompareConvergenceRerouteOntoPathToSameRoot: a branch may be moved onto
198	// a different path that still leads to the same root. branchA1 stops
199	// depending directly on rootA and instead depends on branchA2 (which reaches
200	// rootA); the direct edge rootA -> branchA1 disappears and branchA2 ->
201	// branchA1 appears, but every dataset still reaches the same root set, so the
202	// root-source change list must stay empty. The indirect reachability of rootA
203	// from branchA1 must not be invented as an added direct relation.
204	func TestCompareConvergenceRerouteOntoPathToSameRoot(t *testing.T) {
205		oldSnap := snapshotOf(t, convergenceOldGraph)
206		newSnap := snapshotOf(t, `{"datasets":[
207			{"name":"rootA","upstreams":[]},
208			{"name":"rootB","upstreams":[]},
209			{"name":"branchA1","upstreams":["branchA2"]},
210			{"name":"branchA2","upstreams":["rootA"]},
211			{"name":"branchB1","upstreams":["rootB"]},
212			{"name":"summary","upstreams":["branchA1","branchA2","branchB1"]},
213			{"name":"derived","upstreams":["summary"]},
214			{"name":"soloRoot","upstreams":[]},
215			{"name":"soloChild","upstreams":["soloRoot"]}
216		]}`)
217	
218		report := CompareSnapshots(oldSnap, newSnap)
219		if got, want := report.ChangedDatasets, []string{"branchA1"}; !reflect.DeepEqual(got, want) {
220			t.Errorf("ChangedDatasets = %v, want %v", got, want)
221		}
222		if got, want := report.AddedRelations, []Relation{{Upstream: "branchA2", Downstream: "branchA1"}}; !reflect.DeepEqual(got, want) {
223			t.Errorf("AddedRelations = %v, want %v", got, want)
224		}
225		if got, want := report.RemovedRelations, []Relation{{Upstream: "rootA", Downstream: "branchA1"}}; !reflect.DeepEqual(got, want) {
226			t.Errorf("RemovedRelations = %v, want %v", got, want)
227		}
228		if len(report.RootSourceChanges) != 0 {
229			t.Errorf("a path-only swap to the same root set must not report source changes, got %v", report.RootSourceChanges)
230		}
231		// Sanity-check the rerouted branch still resolves to rootA, now indirectly.
232		if got := rootSources("branchA1", adjacencyFromValidFile(newSnap.Graph)); !reflect.DeepEqual(got, []string{"rootA"}) {
233			t.Errorf("new rootSources(branchA1) = %v, want [rootA]", got)
234		}
235	}
236	
237	// TestCompareConvergenceReportIsDeterministicBytes: record order, upstream
238	// order, and repeated upstreams carry no semantics, so feeding the converging
239	// scenario (the all-paths-rerouted version, which exercises every non-empty
240	// list) in shuffled, duplicated form must produce a byte-identical report.
241	// Comparison also stays read-only: neither input snapshot is modified.
242	func TestCompareConvergenceReportIsDeterministicBytes(t *testing.T) {
243		oldCanonical := snapshotOf(t, convergenceOldGraph)
244		newCanonical := snapshotOf(t, `{"datasets":[
245			{"name":"rootA","upstreams":[]},
246			{"name":"rootB","upstreams":[]},
247			{"name":"branchA1","upstreams":["rootB"]},
248			{"name":"branchA2","upstreams":["rootB"]},
249			{"name":"branchB1","upstreams":["rootB"]},
250			{"name":"summary","upstreams":["branchA1","branchA2","branchB1"]},
251			{"name":"derived","upstreams":["summary"]},
252			{"name":"soloRoot","upstreams":[]},
253			{"name":"soloChild","upstreams":["soloRoot"]}
254		]}`)
255	
256		// Same semantics: records shuffled, summary's upstream list shuffled and
257		// repeated, the repointed branches list their single (repeated) upstream.
258		oldShuffled := snapshotOf(t, `{"datasets":[
259			{"upstreams":["soloRoot"],"name":"soloChild"},
260			{"upstreams":[],"name":"soloRoot"},
261			{"name":"derived","upstreams":["summary","summary"]},
262			{"name":"summary","upstreams":["branchB1","branchA1","branchA2","branchA1"]},
263			{"name":"branchB1","upstreams":["rootB"]},
264			{"name":"branchA2","upstreams":["rootA","rootA"]},
265			{"name":"branchA1","upstreams":["rootA"]},
266			{"name":"rootB","upstreams":[]},
267			{"name":"rootA","upstreams":[]}
268		]}`)
269		newShuffled := snapshotOf(t, `{"datasets":[
270			{"name":"soloChild","upstreams":["soloRoot"]},
271			{"name":"soloRoot","upstreams":[]},
272			{"name":"derived","upstreams":["summary"]},
273			{"upstreams":["branchA2","branchB1","branchA1","branchA2"],"name":"summary"},
274			{"upstreams":["rootB"],"name":"branchB1"},
275			{"upstreams":["rootB","rootB"],"name":"branchA2"},
276			{"upstreams":["rootB"],"name":"branchA1"},
277			{"name":"rootB","upstreams":[]},
278			{"name":"rootA","upstreams":[]}
279		]}`)
280	
281		oldBytesBefore, err := MarshalSnapshot(oldCanonical)
282		if err != nil {
283			t.Fatalf("marshal old snapshot: %v", err)
284		}
285		newBytesBefore, err := MarshalSnapshot(newCanonical)
286		if err != nil {
287			t.Fatalf("marshal new snapshot: %v", err)
288		}
289	
290		want, err := json.Marshal(CompareSnapshots(oldCanonical, newCanonical))
291		if err != nil {
292			t.Fatalf("marshal canonical report: %v", err)
293		}
294		got, err := json.Marshal(CompareSnapshots(oldShuffled, newShuffled))
295		if err != nil {
296			t.Fatalf("marshal shuffled report: %v", err)
297		}
298		if string(got) != string(want) {
299			t.Fatalf("compare bytes differ for semantically equal inputs:\n got %s\nwant %s", got, want)
300		}
301	
302		// Read-only: the snapshot documents handed to the comparison are intact.
303		oldBytesAfter, err := MarshalSnapshot(oldCanonical)
304		if err != nil {
305			t.Fatalf("re-marshal old snapshot: %v", err)
306		}
307		newBytesAfter, err := MarshalSnapshot(newCanonical)
308		if err != nil {
309			t.Fatalf("re-marshal new snapshot: %v", err)
310		}
311		if string(oldBytesAfter) != string(oldBytesBefore) || string(newBytesAfter) != string(newBytesBefore) {
312			t.Errorf("CompareSnapshots mutated an input snapshot")
313		}
314	}
315	
316	// TestCompareConvergenceNoSourceChangesEncodesEmptyArray pins the empty-list
317	// rule on the converging graph: when two versions differ only by a path-only
318	// reroute (and by record/upstream ordering), rootSourceChanges must still
319	// serialize as [], and the whole report is byte-identical across equivalent
320	// inputs.
321	func TestCompareConvergenceNoSourceChangesEncodesEmptyArray(t *testing.T) {
322		oldSnap := snapshotOf(t, convergenceOldGraph)
323		newSnap := snapshotOf(t, `{"datasets":[
324			{"name":"rootA","upstreams":[]},
325			{"name":"rootB","upstreams":[]},
326			{"name":"branchA1","upstreams":["branchA2"]},
327			{"name":"branchA2","upstreams":["rootA"]},
328			{"name":"branchB1","upstreams":["rootB"]},
329			{"name":"summary","upstreams":["branchA1","branchA2","branchB1"]},
330			{"name":"derived","upstreams":["summary"]},
331			{"name":"soloRoot","upstreams":[]},
332			{"name":"soloChild","upstreams":["soloRoot"]}
333		]}`)
334		newShuffled := snapshotOf(t, `{"datasets":[
335			{"upstreams":["summary"],"name":"derived"},
336			{"upstreams":["branchB1","branchA2","branchA1"],"name":"summary"},
337			{"name":"soloChild","upstreams":["soloRoot","soloRoot"]},
338			{"name":"branchA1","upstreams":["branchA2","branchA2"]},
339			{"name":"branchA2","upstreams":["rootA"]},
340			{"name":"branchB1","upstreams":["rootB"]},
341			{"name":"soloRoot","upstreams":[]},
342			{"name":"rootB","upstreams":[]},
343			{"name":"rootA","upstreams":[]}
344		]}`)
345	
346		b1, err := json.Marshal(CompareSnapshots(oldSnap, newSnap))
347		if err != nil {
348			t.Fatalf("marshal report: %v", err)
349		}
350		b2, err := json.Marshal(CompareSnapshots(oldSnap, newShuffled))
351		if err != nil {
352			t.Fatalf("marshal shuffled report: %v", err)
353		}
354		if string(b1) != string(b2) {
355			t.Fatalf("equivalent inputs produced different reports:\n%s\n%s", b1, b2)
356		}
357		if !strings.Contains(string(b1), `"rootSourceChanges":[]`) {
358			t.Errorf("rootSourceChanges must encode as [] when nothing changed source:\n%s", b1)
359		}
360	}
361	
362	// containsString reports whether list contains name.
363	func containsString(list []string, name string) bool {
364		for _, item := range list {
365			if item == name {
366				return true
367			}
368		}
369		return false
370	}
371	
372	// assertNameAbsentFromReport fails if name shows up in any node list or as the
373	// dataset of a root-source change.
374	func assertNameAbsentFromReport(t *testing.T, report *CompareReport, name string) {
375		t.Helper()
376		if containsString(report.NewDatasets, name) {
377			t.Errorf("%q must not be a new dataset; report = %+v", name, report)
378		}
379		if containsString(report.RemovedDatasets, name) {
380			t.Errorf("%q must not be a removed dataset; report = %+v", name, report)
381		}
382		if containsString(report.ChangedDatasets, name) {
383			t.Errorf("%q must not be a directly changed dataset; report = %+v", name, report)
384		}
385		for _, rel := range report.AddedRelations {
386			if rel.Upstream == name || rel.Downstream == name {
387				t.Errorf("%q must not appear in added relations; report = %+v", name, report)
388			}
389		}
390		for _, rel := range report.RemovedRelations {
391			if rel.Upstream == name || rel.Downstream == name {
392				t.Errorf("%q must not appear in removed relations; report = %+v", name, report)
393			}
394		}
395		for _, change := range report.RootSourceChanges {
396			if change.Dataset == name {
397				t.Errorf("%q must not appear in root source changes; report = %+v", name, report)
398			}
399		}
400	}
